{
  "schemaVersion": "0.2",
  "slug": "tab-bar",
  "name": "TabBar",
  "status": "experimental",
  "purpose": "Mobile bottom navigation bar; the compact-screen member of the Navigation morph pair with Sidebar.",
  "scenarios": [
    "Switch between the three to five top-level destinations on a phone",
    "Keep primary navigation reachable by the thumb",
    "Mirror navigation order in RTL locales"
  ],
  "props": {
    "label": {
      "type": "string",
      "required": true,
      "description": "Accessible name of the navigation landmark."
    },
    "items": {
      "type": "string",
      "required": true,
      "description": "Array of destinations with value and label."
    },
    "defaultValue": {
      "type": "string",
      "required": false,
      "description": "Uncontrolled initial active value."
    },
    "value": {
      "type": "string",
      "required": false,
      "description": "Controlled active value."
    },
    "onChange": {
      "type": "event",
      "required": false,
      "description": "Receives the next active value."
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "One destination is active; the bar is docked to the block-end edge."
    }
  ],
  "composition": {
    "allowedParents": [
      "app-shell",
      "page",
      "safe-area"
    ],
    "allowedChildren": [],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use for content switching inside a page; use tabs.",
    "Do not show the tab bar and the sidebar for the same destination set at one breakpoint.",
    "Do not exceed five destinations in the bar."
  ],
  "a11y": {
    "role": "tablist",
    "keyboard": [
      "Tab moves to the active destination",
      "Arrow keys move between destinations (roving tabindex via the tabs primitive)",
      "Enter/Space activates the focused destination"
    ],
    "focus": "Roving tabindex and direction-aware arrow keys are delegated to Ark UI / Zag; visible focus ring on items.",
    "labeling": "The bar is labelled via its label prop; each destination is labelled by its visible text.",
    "wcag": [
      "1.3.1",
      "2.1.1",
      "2.5.5",
      "4.1.2"
    ]
  },
  "responsive": {
    "strategy": "Compact navigation form docked to the block-end edge with env(safe-area-inset-bottom) padding. At tablet/desktop the shell replaces it with Sidebar. Label density adapts via its own container (20rem threshold).",
    "breakpoints": {
      "compact": "Fixed bottom bar; every item hit area >= 44px; safe-area bottom inset applied.",
      "medium": "Composition contract: app-shell shows the collapsible sidebar instead; a directly rendered bar still docks to the block-end edge.",
      "large": "Composition contract: app-shell shows the persistent sidebar instead; a directly rendered bar still docks to the block-end edge."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only; item order follows the document direction and arrow-key roving is direction-aware via the primitive.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "tab-bar",
    "states": [
      "active"
    ],
    "intents": [
      "navigate-sections"
    ]
  }
}

/*
 * Phase 5 container-query whitelist member: the bar is fixed to the block-end
 * viewport edge and is its own query container; labels shrink only when the
 * bar itself is narrow, regardless of how the viewport got there.
 * The block-end padding consumes the device safe-area inset (with a 0px
 * fallback) so the home indicator never covers tabs.
 */
.cu-tab-bar {
  position: fixed;
  inset-block-end: 0;
  inset-inline: 0;
  z-index: 20;
  padding-block-end: env(safe-area-inset-bottom, 0px);
  border-block-start: var(--cu-border-width-hairline, 1px) solid var(--cu-color-border-default);
  background: var(
    --cu-color-background-translucent,
    var(--cu-color-background-elevated, var(--cu-color-background-default))
  );
  -webkit-backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  backdrop-filter: saturate(var(--cu-saturate-frost, 1)) blur(var(--cu-blur-surface, 0px));
  color: var(--cu-color-fg-default);
  container-type: inline-size;
}

.cu-tab-bar__list {
  display: flex;
  align-items: stretch;
}

.cu-tab-bar__item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--cu-space-1);
  min-block-size: var(--cu-touch-target-min);
  padding-block: var(--cu-space-1);
  padding-inline: var(--cu-space-2);
  border: none;
  border-block-start: 2px solid transparent;
  background: transparent;
  color: var(--cu-color-fg-default);
  font: inherit;
  font-size: 0.875rem;
  cursor: pointer;
}

.cu-tab-bar__item:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
}

.cu-tab-bar__item[data-state='active'] {
  border-block-start-color: var(--cu-color-palette-brand);
  color: var(--cu-color-palette-brand);
  font-weight: 700;
}

@media (hover: hover) {
  .cu-tab-bar__item:hover:not([data-state='active']) {
    background: color-mix(in srgb, var(--cu-color-background-default) 92%, var(--cu-color-palette-brand));
  }
}

/* Component-local container threshold: very narrow bars shrink labels (contract responsive). */
@container (max-width: 20rem) {
  .cu-tab-bar__item {
    font-size: 0.75rem;
    padding-inline: var(--cu-space-1);
  }
}

@media (prefers-reduced-motion: reduce) {
  .cu-tab-bar__item {
    transition-duration: 0.01ms;
  }
}

import { TabsPrimitive } from '@chameleon-ui/primitives'
import type { ReactNode } from 'react'
import './styles.css'

export interface TabBarItem {
  value: string
  label: ReactNode
}

export interface TabBarProps {
  /** Accessible name of the navigation landmark. */
  label: string
  items: TabBarItem[]
  defaultValue?: string
  value?: string
  onChange?: (value: string) => void
  className?: string
}

export function TabBar({ label, items, defaultValue, value, onChange, className }: TabBarProps) {
  const classes = ['cu-tab-bar', className].filter(Boolean).join(' ')
  const active = value ?? defaultValue ?? items[0]?.value ?? 'default'

  return (
    <TabsPrimitive.Root
      className={classes}
      data-ai-role="tab-bar"
      data-ai-intent="navigate-sections"
      data-ai-state={active}
      defaultValue={defaultValue ?? items[0]?.value}
      value={value}
      onValueChange={(details) => onChange?.(details.value)}
    >
      <TabsPrimitive.List className="cu-tab-bar__list" aria-label={label}>
        {items.map((item) => (
          <TabsPrimitive.Trigger key={item.value} className="cu-tab-bar__item" value={item.value}>
            <span className="cu-tab-bar__label">{item.label}</span>
          </TabsPrimitive.Trigger>
        ))}
      </TabsPrimitive.List>
    </TabsPrimitive.Root>
  )
}
